AWS API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("aws_api_gateway", "AWS API Gateway") {
    Component(mtls_endpoint_configuration, "mTLS Endpoint Configuration", "AWS API Gateway mTLS", "Provides secure ingress authentication for payment gateways and acquirers.")
    Component(aws_waf, "AWS WAF", "AWS Web Application Firewall", "Inspects ingress traffic for rate-limiting and security.")
    Component(request_validator, "Request Validator", "AWS API Gateway Validator", "Validates payment authorization request payloads before processing.")
}

Rel(mtls_endpoint_configuration, aws_waf, "Inspects traffic", "AWS Internal")
Rel(aws_waf, request_validator, "Passes validated traffic", "AWS Internal")

@enduml

Amazon Aurora Serverless v2.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_aurora_serverless_v2, "Amazon Aurora Serverless v2") {
    Component(fraud_scoring_data_store, "Fraud Scoring Data Store", "PostgreSQL, pgcrypto, Table Partitioning", "Handles write-heavy fraud scoring records and column-level encryption for audit compliance.")
    Component(case_management_data_store, "Case Management Data Store", "PostgreSQL", "Stores case data and audit histories accessed via read replica routing.")
}

Rel(fraud_scoring_data_store, case_management_data_store, "Replicates data for read operations and audit history queries", "Replication")

@enduml
